input.sparql:
SELECT ?point WHERE {
  ?point brick:hasParent ?b .
  ?point a ?c .
  FILTER(?c = brick:ElectricPower || ?c = brick:ElectricEnergy || ?c = brick:ElectricCurrent)
} LIMIT 50

SELECT DISTINCT ?c WHERE {
  ?point a ?c .
  FILTER(str(?c) LIKE "%lectric%")
} LIMIT 50

SELECT ?point ?c ?ts ?bld WHERE {
  ?point a ?c .
  ?point ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point brick:hasParent ?bld }
} LIMIT 200
